import{_ as t,o as a,c as r,a5 as i}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"UC 05 — AI Features (UC-74 → UC-82)","description":"","frontmatter":{},"headers":[],"relativePath":"ba/use-cases/05-ai-features.md","filePath":"ba/use-cases/05-ai-features.md"}'),o={name:"ba/use-cases/05-ai-features.md"};function n(s,e,l,d,c,g){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="uc-05-—-ai-features-uc-74-→-uc-82" tabindex="-1">UC 05 — AI Features (UC-74 → UC-82) <a class="header-anchor" href="#uc-05-—-ai-features-uc-74-→-uc-82" aria-label="Permalink to &quot;UC 05 — AI Features (UC-74 → UC-82)&quot;">​</a></h1><p>&gt; <a href="./../00-overview.html">&lt;&lt; Về Overview</a> · Nguồn FR: <a href="./../06-ai-features.html">06-ai-features.md</a> &gt; Nguồn UC gốc: <code>Các FR của hệ thống - Use Case.csv</code></p><h2 id="bang-tong-hop" tabindex="-1">Bảng tổng hợp <a class="header-anchor" href="#bang-tong-hop" aria-label="Permalink to &quot;Bảng tổng hợp&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UC ID</th><th>Use Case</th><th>Actor(s)</th><th>Related FR</th></tr></thead><tbody><tr><td>UC-74</td><td>View Trending Topics &amp; Hashtag Suggestions</td><td>CREATOR</td><td>3.7.1, 3.7.10</td></tr><tr><td>UC-75</td><td>Generate Caption with AI</td><td>CREATOR</td><td>3.7.2</td></tr><tr><td>UC-76</td><td>Generate AI Brand Ambassador</td><td>CREATOR</td><td>3.7.3</td></tr><tr><td>UC-77</td><td>Generate Image with AI</td><td>CREATOR</td><td>3.7.4, 3.7.5</td></tr><tr><td>UC-78</td><td>Generate Video with AI</td><td>CREATOR</td><td>3.7.6, 3.7.7</td></tr><tr><td>UC-79</td><td>Export AI-Generated File</td><td>CREATOR</td><td>3.7.8</td></tr><tr><td>UC-80</td><td>Configure Trend Crawl Schedule</td><td>ADMIN</td><td>3.7.9</td></tr><tr><td>UC-81</td><td>Generate Livestream Script with AI</td><td>CREATOR</td><td>3.7.11</td></tr><tr><td>UC-82</td><td>Recommend Media Collaborator</td><td>CREATOR</td><td>3.7.12</td></tr></tbody></table><hr><h2 id="uc-74-—-view-trending-topics-hashtag-suggestions" tabindex="-1">UC-74 — View Trending Topics &amp; Hashtag Suggestions <a class="header-anchor" href="#uc-74-—-view-trending-topics-hashtag-suggestions" aria-label="Permalink to &quot;UC-74 — View Trending Topics &amp; Hashtag Suggestions&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> CREATOR</li><li><strong>Description:</strong> View a dashboard of current trending keywords and suggested trending hashtags.</li><li><strong>Precondition:</strong> Trend crawl data available (see UC-80).</li><li><strong>Main Flow:</strong><ol><li>CREATOR opens Trending Topics dashboard.</li><li>System displays current trend keywords + AI-suggested trending hashtags.</li></ol></li></ul><h2 id="uc-75-—-generate-caption-with-ai" tabindex="-1">UC-75 — Generate Caption with AI <a class="header-anchor" href="#uc-75-—-generate-caption-with-ai" aria-label="Permalink to &quot;UC-75 — Generate Caption with AI&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> CREATOR</li><li><strong>Description:</strong> Use an LLM and prompt to generate a caption for a post.</li><li><strong>Precondition:</strong> CREATOR has an active AI credit balance.</li><li><strong>Main Flow:</strong><ol><li>CREATOR enters a prompt/context for the post.</li><li>System sends the request to the LLM, returns a generated caption.</li><li>AI credit deducted for the generation.</li></ol></li></ul><h2 id="uc-76-—-generate-ai-brand-ambassador" tabindex="-1">UC-76 — Generate AI Brand Ambassador <a class="header-anchor" href="#uc-76-—-generate-ai-brand-ambassador" aria-label="Permalink to &quot;UC-76 — Generate AI Brand Ambassador&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> CREATOR</li><li><strong>Description:</strong> Use an LLM to generate a virtual model/ambassador when the brand has none, used for Image/Video generation.</li><li><strong>Precondition:</strong> Brand has no real ambassador/model on file.</li><li><strong>Main Flow:</strong><ol><li>CREATOR requests ambassador generation (style/appearance input).</li><li>System generates a virtual &quot;actor&quot; via LLM.</li></ol></li><li><strong>Postcondition:</strong> Ambassador saved and reusable as an input source for UC-77 (Generate Image) and UC-78 (Generate Video) — not a standalone one-off feature.</li></ul><h2 id="uc-77-—-generate-image-with-ai" tabindex="-1">UC-77 — Generate Image with AI <a class="header-anchor" href="#uc-77-—-generate-image-with-ai" aria-label="Permalink to &quot;UC-77 — Generate Image with AI&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> CREATOR</li><li><strong>Description:</strong> Select an image style template and generate an image via LLM based on form input, model, and other materials.</li><li><strong>Precondition:</strong> CREATOR has an active AI credit balance.</li><li><strong>Main Flow:</strong><ol><li>CREATOR selects an image style template (anime, spring, nostalgic, etc.).</li><li>CREATOR fills a form; system combines form + Ambassador model (if any) + Material Repository/Brand Collection assets into a single prompt.</li><li>System calls the image-gen LLM (LoRA fine-tuned for brand style where applicable), returns generated image(s).</li><li>AI credit deducted.</li></ol></li></ul><h2 id="uc-78-—-generate-video-with-ai" tabindex="-1">UC-78 — Generate Video with AI <a class="header-anchor" href="#uc-78-—-generate-video-with-ai" aria-label="Permalink to &quot;UC-78 — Generate Video with AI&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> CREATOR</li><li><strong>Description:</strong> Select a video style template and generate a video via LLM/third-party APIs.</li><li><strong>Precondition:</strong> CREATOR has an active AI credit balance.</li><li><strong>Main Flow:</strong><ol><li>CREATOR selects a video style template.</li><li>System builds prompt/input, calls third-party video-gen API.</li><li>AI credit deducted, generated video returned.</li></ol></li></ul><h2 id="uc-79-—-export-ai-generated-file" tabindex="-1">UC-79 — Export AI-Generated File <a class="header-anchor" href="#uc-79-—-export-ai-generated-file" aria-label="Permalink to &quot;UC-79 — Export AI-Generated File&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> CREATOR</li><li><strong>Description:</strong> Export generated files (images/videos) from the system to the user&#39;s device.</li><li><strong>Precondition:</strong> A generated file exists (UC-77/UC-78).</li><li><strong>Main Flow:</strong><ol><li>CREATOR selects Export on a generated file.</li><li>System exports in the appropriate format (mainly MP4/WebM for social upload).</li></ol></li><li><strong>Note:</strong> Reusing a previously generated asset does not deduct AI credit again (see FR 3.6.35).</li></ul><h2 id="uc-80-—-configure-trend-crawl-schedule" tabindex="-1">UC-80 — Configure Trend Crawl Schedule <a class="header-anchor" href="#uc-80-—-configure-trend-crawl-schedule" aria-label="Permalink to &quot;UC-80 — Configure Trend Crawl Schedule&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> ADMIN</li><li><strong>Description:</strong> Configure timing, source pages, and volume per run for the crawler that collects trending keyword data.</li><li><strong>Precondition:</strong> User is ADMIN.</li><li><strong>Main Flow:</strong><ol><li>ADMIN sets crawl schedule (frequency, source pages, posts-per-run volume).</li><li>System applies the config to the trend-crawling job.</li></ol></li><li><strong>Note:</strong> This is the only AI-group FR owned by ADMIN (not CREATOR) — crawler config affects system-wide resources, not a per-Workspace action.</li></ul><h2 id="uc-81-—-generate-livestream-script-with-ai" tabindex="-1">UC-81 — Generate Livestream Script with AI <a class="header-anchor" href="#uc-81-—-generate-livestream-script-with-ai" aria-label="Permalink to &quot;UC-81 — Generate Livestream Script with AI&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> CREATOR</li><li><strong>Description:</strong> Use AI to generate a sample script for a livestream session.</li><li><strong>Precondition:</strong> Livestream idea exists (see <a href="./04-content-task-workflow.html">04-content-task-workflow.md</a> UC-61).</li><li><strong>Main Flow:</strong><ol><li>CREATOR requests an AI-generated draft script.</li><li>System returns a sample script, which the Creator then edits/finalizes (UC-62, Write Livestream Script).</li></ol></li></ul><h2 id="uc-82-—-recommend-media-collaborator" tabindex="-1">UC-82 — Recommend Media Collaborator <a class="header-anchor" href="#uc-82-—-recommend-media-collaborator" aria-label="Permalink to &quot;UC-82 — Recommend Media Collaborator&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> CREATOR</li><li><strong>Description:</strong> AI recommends third parties (online newspapers, banner ad channels, TV channels) as media partners for the campaign.</li><li><strong>Precondition:</strong> Active Media Campaign context.</li><li><strong>Main Flow:</strong><ol><li>CREATOR/Manager requests collaborator suggestions.</li><li>System returns a ranked list of potential Third-party Collaborators.</li></ol></li><li><strong>Business Rule:</strong> AI only suggests — final selection/contact decision remains with Client/Manager, no auto-contact or auto-signing. See <a href="./../07-publishing-social-collaborator.html">07-publishing-social-collaborator.md</a> §2.</li></ul>',23)])])}const m=t(o,[["render",n]]);export{u as __pageData,m as default};
